effect.shader:
void main() {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = acScreenNorm;

    // --- Apply Directional Skew ---
    // Center the coordinates on the layer center
    vec2 centered = uv - acLayerCenterNorm;

    // Calculate rotation based on Angle
    float rad = radians(skewAngle);
    float c = cos(rad);
    float s = sin(rad);

    // Rotation matrices
    // mat2(column0, column1)
    mat2 toSkewAxis = mat2(c, -s, s, c);
    mat2 fromSkewAxis = mat2(c, s, -s, c);

    // 1. Rotate to align with skew axis
    vec2 temp = centered * toSkewAxis;

    // 2. Apply Skew (Shear)
    // 'skewScale' determines the strength of the shear
    temp.x += temp.y * skewScale;

    // 3. Rotate back
    centered = temp * fromSkewAxis;

    // Restore coordinates
    uv = centered + acLayerCenterNorm;

    // Sample the texture
    // We ensure we dont sample outside 0-1 if needed, but standard behavior usually crops or wraps
    gl_FragColor = texture2DCv(inputImg.texture, uv);
}
